const r=[];
for(let i=0;i<3;i++){const e=await nodes.next();r.push(e.lines.join("\n"));if(/n2\.r1/.test(r.join())&&/n3\.r1/.test(r.join())&&/n4\.r1/.test(r.join()))break;}
return r.join("\n");

// J1: Can Caldrian utilities finance 2027 capex through debt markets?
// J2: Can Caldrian utilities finance 2027 capex through equity markets?
globalThis.a=nodes.open({task:"Can Caldrian utilities finance their 2027 capex plans through debt markets?"});
globalThis.b=nodes.open({task:"Can Caldrian utilities finance their 2027 capex plans through equity markets?"});
const r=await Promise.all([a.result(),b.result()]);
return r.map(x=>x.ref+" "+x.line+"\n"+"").join("\n")+"\n"+(await read(r[0].ref))+"\n----\n"+(await read(r[1].ref));

let out="";
for(let i=0;i<10;i++){const e=await nodes.next();out+=e.lines.join("\n")+"\n";if(/n3\.r1/.test(out)&&/n4\.r1/.test(out))break;}
return out;
